import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['5ad39f093b9d3a1068d18d41a3e45a86'],
        name: 'High priority incident handling flow',
        description:
            'Flow that triggers when a P1 or P2 incident is created, sends emails based on priority, and creates incident task',
        runAs: 'user',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['3bd3d3493b9d3a1068d18d41a3e45a28'] },
        {
            condition: 'priority=1^ORpriority=2',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
            table: 'incident',
        }
    ),
    (params) => {
        wfa.flowLogic.if(
            {
                condition: '{{Created_1.current.priority}}=1',
                annotation: 'Check if incident priority is P1 - Critical',
                $id: Now.ID['c90457493b9d3a1068d18d41a3e45a7c'],
            },
            () => {
                wfa.action(
                    'c1806bf4a70323008299b39f087901cb',
                    {
                        $id: Now.ID['8e34db493b9d3a1068d18d41a3e45a57'],
                        annotation: 'Send P1 incident email to manager and support',
                        uuid: 'd70e0eae-36a9-4d28-904f-b6822a8699b3',
                    },
                    {
                        ah_to: '{{Created_1.current.assigned_to.manager.email}} ',
                        watermark_email: true,
                        ah_bcc: '',
                        record: wfa.dataPill(params.trigger.current, 'reference'),
                        ah_body:
                            '<p data-tinymcerootblock="">P1 incident is created, look into it on very high priority !!!</p>',
                        table_name: 'incident',
                        ah_subject: 'P1 incident alert',
                        ah_cc: 'p1support@servicenow.com',
                    }
                )
            }
        )
        wfa.flowLogic.elseIf(
            {
                condition: '{{Created_1.current.priority}}=2',
                annotation: 'Check if incident priority is P2 - High',
                $id: Now.ID['1b9453893b9d3a1068d18d41a3e45ad8'],
            },
            () => {
                wfa.action(
                    'c1806bf4a70323008299b39f087901cb',
                    {
                        $id: Now.ID['87a417893b9d3a1068d18d41a3e45a00'],
                        annotation: 'Send email to incident assigned to',
                        uuid: '433e0f13-6177-4546-84a1-de350de0ffec',
                    },
                    {
                        ah_to: '{{Created_1.current.assigned_to.email}} ',
                        watermark_email: true,
                        ah_bcc: '',
                        record: '{{Created_1.current}}',
                        ah_body:
                            '<p data-tinymcerootblock=""><span data-slate-fragment="">High priority incident is created, please look into it actively !!!</span></p>',
                        table_name: 'incident',
                        ah_subject: 'High priority incident is created',
                        ah_cc: '',
                    }
                )
            }
        )
        wfa.action(
            '2de05916c31332002841b63b12d3aee1',
            {
                $id: Now.ID['1fd4d7893b9d3a1068d18d41a3e45a8b'],
                annotation: 'Create incident task and assigned to same as incident',
                uuid: 'c6aae135-3787-4b15-b8d2-c7dfda525761',
            },
            {
                values: 'short_description={{Created_1.current.short_description}}^assigned_to={{Created_1.current.assigned_to}}',
                table_name: 'incident_task',
            }
        )
    }
)
